def check(s):
    arr = list(s)
    n = len(arr)
    while True:
        a = 4 
        b = -1 
        for i in range(n -1 , 0 , -1 ):
            if int(arr[i]) > a:
                b = i 
                break
            a = 3 if a ==4 else 4
        if b == -1:
            break
        arr[b-1] = str(int(arr[b-1]) + 1)
        for j in range(b , n):
            arr[j] = '0'
        if int(arr[0]) > 9:
            arr[0]='0'
            arr = ['1'] + arr
            n += 1
    return ''.join(arr)
t = int(input())
for _ in range(t):
    print(check(input().strip()))

